/* nodes details for region "systems", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("systems.nodes",{"nodes":{
"water-cycle":{"description":{"zh":"海洋、空气、陆地三个水库之间的蒸发、降水与径流使总量守恒，各处水量收敛到稳定值。速率常数为教学示意值。","en":"Evaporation, rain and runoff between ocean, air and land reservoirs conserve the total and settle each store at a steady value. Rate constants are illustrative."},"formula":"A* = k_e·O* / k_p","source":"../earth/climate/water-cycle/#step4","lessons":[{"slug":"water-cycle","step":4,"category":"earth","stage":"primary","primary":true}],"aliases":{"zh":["水循环","下雨","为什么会下雨","降雨","雨是怎么形成的","蒸发"],"en":["water cycle","rain","how does rain form","precipitation","evaporation"]}},
"energy-pyramid":{"description":{"zh":"生产者固定阳光、逐级约一成传递、顶级捕食者所需面积、三种金字塔与饮食的土地账；示例量级的教学模型。","en":"Producers fixing sunlight, roughly ten percent passing up each level, the area top predators need, three kinds of pyramid and the land ledger of diets; a teaching model with example magnitudes."},"formula":"E_k = E_producers × eff^(k−1)","source":"../biology/ecology/energy-pyramid/#step1","lessons":[{"slug":"energy-pyramid","step":1,"category":"biology","stage":"junior","primary":true}],"note":"group systems is the closest of the five atlas groups (flows through stages); the page is ecology"},
"mechanical-energy":{"description":{"zh":"无摩擦时动能与重力势能之和守恒，速度由高度差决定；有摩擦时减少的机械能变成热，E_p + E_k + Q 仍守恒；同一本账给出圆环的最低高度 2.5R、弹簧弹起高度和刹车距离 v²/(2μg)。质点模型，无空气阻力。","en":"Without friction the sum of kinetic and gravitational potential energy is conserved and speed follows from the height difference; with friction the lost mechanical energy becomes heat and E_p + E_k + Q is still conserved; the same ledger gives the minimum loop height 2.5R, the height of a spring launch and the braking distance v²/(2μg). A point-mass model without air resistance."},"formula":"E_p + E_k = mgh + ½mv² = const","source":"../physics/mechanics/mechanical-energy/#step1","lessons":[{"slug":"mechanical-energy","step":1,"category":"physics","stage":"junior","primary":true}],"note":"Edges use atlas node work-energy."},
"activation-energy":{"description":{"zh":"反应要翻过一座能量山：只有能量超过山顶的分子才能反应，升温让超过山顶的分子比例指数式增加，所以速率随温度急剧上升（k = A·e^(−Eₐ/RT) 中的玻尔兹曼因子）；催化剂不加热，而是把山本身降低，逆反应同理。最简形式，忽略取向因子与熵。","en":"A reaction must climb an energy hill: only molecules above the top can react, and warming raises that fraction exponentially, so the rate climbs steeply with temperature (the Boltzmann factor in k = A·e^(−Eₐ/RT)). A catalyst does not heat things up — it lowers the hill itself, and the reverse reaction follows the same picture. Simplest form, ignoring orientation factors and entropy."},"formula":"k = A e^(−Eₐ/RT)","source":"../chemistry/reactions/activation-energy/#step2","lessons":[{"slug":"activation-energy","step":2,"category":"chemistry","stage":"senior","primary":true}],"note":"group systems is the closest existing atlas group (rates and responses); the page is chemical kinetics","aliases":{"zh":["玻尔兹曼因子"],"en":["boltzmann factor"]}},
"dna-replication":{"description":{"zh":"复制靠碱基配对（A 对 T、G 对 C）照着旧链拼新链，子代 DNA 各留一条旧链，这就是半保留复制；随后信息从 DNA 转录成 RNA、再翻译成蛋白质，一个碱基的点突变就可能改变一个氨基酸。标准密码表，忽略链方向与大量酶学细节。","en":"Copying works by base pairing (A with T, G with C): each new strand is built against an old one, so every daughter DNA keeps one old strand — semi-conservative replication. The message is then transcribed from DNA to RNA and translated into protein, where a single-base point mutation can change one amino acid. Standard code table, ignoring strand direction and most enzymology."},"formula":"mRNA codon (3 bases) → amino acid","source":"../biology/cells/dna-replication/#step3","lessons":[{"slug":"dna-replication","step":3,"category":"biology","stage":"senior","primary":true}],"note":"group systems is the closest of the five atlas groups (information flowing through a process); the page is molecular biology","aliases":{"zh":["蛋白质合成","蛋白质是怎么合成的","中心法则","转录","mRNA","核糖体"],"en":["protein synthesis","how are proteins made","central dogma","transcription","mRNA","ribosome","gene expression"]}},
"enzymes":{"description":{"zh":"酶像一把专配的锁钥：底物少时酶空闲着，速率随浓度涨；底物多了，酶分子全被占满，速率就饱和了——这就是米氏曲线的平台；温度与 pH 各有最适点，偏离则酶变形失活；抑制剂或抢位置（竞争性），或另找结合位点拖慢酶（非竞争性）。单底物稳态教学模型。","en":"An enzyme fits its substrate like a lock and key: with little substrate most enzymes sit idle and the rate rises with concentration, but with plenty of substrate every enzyme is occupied and the rate saturates — the plateau of the Michaelis–Menten curve. Temperature and pH each have an optimum, away from which the enzyme deforms and fails; inhibitors either compete for the same spot (competitive) or bind elsewhere and slow the enzyme (non-competitive). A single-substrate steady-state teaching model."},"formula":"v = Vmax[S]/(Kₘ + [S])","source":"../biology/cells/enzymes/#step1","lessons":[{"slug":"enzymes","step":1,"category":"biology","stage":"senior","primary":true}],"note":"group systems is the closest of the five atlas groups (input–response with saturation); the page is biochemistry"},
"gravity-orbits":{"description":{"zh":"平方反比引力下，横向发射速度决定轨道：低于圆速度为椭圆，等于为圆，达到 √2 倍圆速度逃逸；能量与角动量守恒给出近远点和等面积定律，T² ∝ a³。牛顿两体模型，数值积分。","en":"Under an inverse-square pull the sideways launch speed decides the orbit: an ellipse below the circular speed, a circle at it, an escape at √2 times it; conservation of energy and angular momentum give the apsides and the equal-areas law, and T² ∝ a³. A Newtonian two-body model with numerical integration."},"formula":"T² = 4π² a³ / GM","source":"../earth/astronomy/gravity-orbits/#step4","lessons":[{"slug":"gravity-orbits","step":4,"category":"earth","stage":"senior","primary":true}],"note":"Edges use atlas nodes net-force and work-energy.","aliases":{"zh":["重力","引力","卫星为什么不会掉下来","卫星轨道"],"en":["gravity","why don't satellites fall","satellite orbit"]}},
"pid-controller":{"description":{"zh":"PID 控制器按误差 e = 目标 − 输出来决定推多少：P 按现在差多少来推，I 把过去残留的误差累加起来消掉稳态误差，D 看误差变化的快慢提前刹车；三项调得不好，系统就会太慢、冲过头或被噪声带着抖。","en":"A PID controller decides how hard to push from the error e = target − output: P pushes in proportion to the present error, I accumulates past leftover error to remove the steady-state offset, and D watches how fast the error changes to brake early; tuned badly, the loop is sluggish, overshoots or jitters with noise."},"formula":"u = Kp·e + Ki∫e dt + Kd·de/dt","source":"../engineering/control/pid-control/#step1","lessons":[{"slug":"pid-control","step":1,"category":"engineering","stage":"senior","primary":true}],"aliases":{"zh":["PID 控制器","比例 积分 微分","PID 调参","稳态误差","积分饱和","超调","恒温器和定速巡航怎么控制"],"en":["PID controller","proportional, integral, derivative","PID tuning","steady-state error","integral windup","overshoot","how do thermostats and cruise control work"]}},
"step-response":{"description":{"zh":"给一个带质量、弹簧和阻尼的系统一个突然的目标跳变，输出怎样追过去由两个数决定：阻尼比 ζ 决定冲过头多少（超调只看 ζ），固有频率 ωn 决定整条曲线在时间上被压缩还是拉长；两者合起来就是复平面上的一对极点。","en":"Give a system with mass, spring and damping a sudden jump in its target, and how the output follows is set by two numbers: the damping ratio ζ decides how far it overshoots (overshoot depends on ζ alone), and the natural frequency ωn squeezes or stretches the whole curve in time; together they are one pair of poles in the complex plane."},"formula":"Mp = e^(−ζπ/√(1−ζ²))","source":"../engineering/control/step-response/#step2","lessons":[{"slug":"step-response","step":2,"category":"engineering","stage":"senior","primary":true}],"aliases":{"zh":["阶跃响应","阻尼比","欠阻尼 临界阻尼 过阻尼","超调量","调节时间","二阶系统","固有频率"],"en":["step response","damping ratio","underdamped, critically damped, overdamped","percent overshoot","settling time","second-order system","natural frequency"]}},
"attention-mechanism":{"description":{"zh":"查询与键的点积给出分数，softmax 变成权重，对值向量加权求和得到输出。本页是手工设定的二维玩具模型，不是训练出的网络。","en":"Query-key dot products give scores, softmax turns them into weights, and a weighted sum of value vectors gives the output. This page is a hand-set 2-D toy, not a trained network."},"formula":"o = softmax(q·kᵢ/√d)·V","source":"../computing/ml/attention-mechanism/#step2","lessons":[{"slug":"attention-mechanism","step":2,"category":"computing","stage":"university","primary":true}],"aliases":{"zh":["自注意力"],"en":["transformer","transformers","self-attention"]}},
"backpropagation":{"description":{"zh":"用链式法则把损失的责任从输出一路往回乘到每个权重：一次向后扫描就得到全部梯度，而不用逐个权重挨个扰动试错——这正是反向传播省下的算力；梯度到手后，权重就沿着减小的方向走一小步。本页是单路径极小网络，不是训练真实模型。","en":"The chain rule multiplies the loss's blame backwards from the output to every weight: one backward sweep yields all gradients, instead of perturbing each weight one by one to see what helps — that saved computation is the point of backpropagation. With gradients in hand, each weight takes a small step downhill. The page uses a tiny single-path network, not a real training run."},"formula":"∂L/∂w = ∂L/∂ŷ · ∂ŷ/∂h · ∂h/∂a · ∂a/∂w","source":"../computing/ml/backpropagation/#step2","lessons":[{"slug":"backpropagation","step":2,"category":"computing","stage":"university","primary":true}],"aliases":{"zh":["链式法则"],"en":["chain rule"]}},
"chaos-threebody":{"description":{"zh":"确定的规则也能产生无法长期预测的行为：误差按 e^{λt} 放大（λ > 0），可预测期限只与精度的对数成正比；洛伦兹吸引子与三体 8 字轨道是典型例子。数值模型，长轨迹细节不可信。","en":"Deterministic rules can produce behaviour that cannot be predicted long term: errors grow like e^{λt} with λ > 0, and the prediction horizon is proportional only to the logarithm of the precision; the Lorenz attractor and the three-body figure-8 are typical examples. A numerical model; fine detail of long trajectories is not trustworthy."},"formula":"δ(t) ≈ δ₀ e^{λt}","source":"../physics/mechanics/chaos-threebody/#step3","lessons":[{"slug":"chaos-threebody","step":3,"category":"physics","stage":"university","primary":true}],"note":"Edges use existing atlas nodes feedback and oscillation where they exist; chaos-threebody is a new concept id."},
"convolution":{"description":{"zh":"把一个序列翻转、平移，与另一个序列对应相乘后求和；每个位移产生一个输出值——实际就是加权滑动平均：用它平滑信号、模糊图像时，权重序列就是“邻居各占几分”的配方。","en":"Reverse and shift one sequence, multiply it against another, then sum; each shift produces one output value. In practice it is a weighted moving average — smoothing a signal or blurring an image just picks a weight sequence saying how much each neighbour counts."},"formula":"y[n] = Σ x[k]h[n−k]","source":"../signal/systems/convolution/#step2","lessons":[{"slug":"convolution","step":2,"category":"signal","stage":"university","primary":true}]},
"feedback":{"description":{"zh":"测量输出，与目标比较，再据此调整输入。反馈效果取决于控制器、系统、延迟及噪声。","en":"Measure an output, compare it with a target, and adjust the input. Results depend on the controller, system, delay and noise."},"formula":"measure → compare → act","source":"../signal/control/inverted-pendulum/#step2","lessons":[{"slug":"inverted-pendulum","step":2,"category":"signal","stage":"university","primary":true}]},
"freqresp":{"description":{"zh":"对稳定 LTI 系统，频率响应描述正弦输入的稳态幅度与相位变化。连续时间（CT）用 H(iω)，ω 单位 rad/s；离散时间（DT）用 H(e^{iΩ})，Ω 单位 rad/样本。","en":"For a stable LTI system, frequency response describes steady-state sinusoidal amplitude and phase changes. Continuous time (CT) uses H(iω), with ω in rad/s; discrete time (DT) uses H(e^{iΩ}), with Ω in rad/sample."},"formula":"CT: H(iω); DT: H(e^{iΩ})","source":"../signal/systems/frequency-response/#step0","lessons":[{"slug":"frequency-response","step":0,"category":"signal","stage":"university","primary":true}]},
"gradient-descent":{"description":{"zh":"沿着斜率往下走：每步算损失对每个参数的斜率，参数就往斜率的反方向挪一小步，步长叫学习率。步子太大来回震荡、太小走不到底；一次只看一批数据的叫小批量，是算力与稳定的折中。","en":"Walk downhill along the slope: each step computes the loss's slope for every parameter, and each parameter moves a small step against the slope; the step size is the learning rate. Too big a step oscillates, too small never arrives; looking at one batch at a time is the mini-batch compromise between compute and stability."},"formula":"θ ← θ − α∇J","source":"../computing/ml/gradient-descent/#step0","lessons":[{"slug":"gradient-descent","step":0,"category":"computing","stage":"university","primary":true}],"aliases":{"zh":["随机梯度下降","SGD"],"en":["stochastic gradient descent","SGD"]}},
"impulse":{"description":{"zh":"给离散系统输入一个单位脉冲后得到的输出。对初始静止的线性时不变系统，它足以确定任意输入的响应。","en":"The output produced by a discrete unit impulse. For an initially resting LTI system, it determines the response to any input."},"formula":"δ[n] → h[n]","source":"../signal/systems/lti-systems/#step2","lessons":[{"slug":"lti-systems","step":2,"category":"signal","stage":"university","primary":true}]},
"lti":{"description":{"zh":"线性意味着输入加权组合对应输出的同样组合（可以分开算再叠加）；时不变意味着系统今天和明天一个样——输入推迟多久，输出就推迟多久，形状不变。","en":"Linearity preserves weighted combinations of inputs (solve parts separately, then add); time invariance means the system behaves the same today and tomorrow — delay the input and the output delays by exactly as much, shape unchanged."},"formula":"linear + time invariant","source":"../signal/systems/lti-systems/#step3","lessons":[{"slug":"lti-systems","step":3,"category":"signal","stage":"university","primary":true}]},
"ode-phase-portraits":{"description":{"zh":"用捕食者—猎物模型对比时间曲线与相平面，找零线与平衡点，验证守恒量 H 并看欧拉法的数值漂移，再加拥挤项把闭圈变成螺旋。两个种群、连续数量、规则固定。","en":"Compare time curves with the phase plane for a predator–prey model, find nullclines and the equilibrium, check the conserved quantity H and the drift of Euler’s method, then add crowding to turn loops into spirals. Two populations, continuous counts, fixed rules."},"formula":"x′ = ax − bxy, y′ = −cy + dxy","source":"../math/calculus/ode-phase-portraits/#step2","lessons":[{"slug":"ode-phase-portraits","step":2,"category":"math","stage":"university","primary":true}],"aliases":{"zh":["微分方程","常微分方程"],"en":["differential equation","differential equations","ODE"]}},
"poles":{"description":{"zh":"极点关联响应中的指数模式。连续时间因果有理系统的传递函数极点全在左半平面时，输入输出稳定。","en":"Poles describe exponential response modes. A causal continuous-time rational system is input-output stable when all transfer-function poles lie in the left half-plane."},"formula":"Re(p) < 0","source":"../signal/transforms/laplace/#step4","lessons":[{"slug":"laplace","step":4,"category":"signal","stage":"university","primary":true}]},
"prisoners-dilemma":{"description":{"zh":"从一次博弈中背叛占优，到重复博弈、循环赛、继续概率阈值 δ* 与三策略复制者动态，再到噪声下宽容的价值。两人两动作、固定收益 5/3/1/0、无突变的简化模型。","en":"From defection dominating a single round, through repeated play, a round-robin, the continuation threshold δ* and three-strategy replicator dynamics, to the value of forgiveness under noise. A simplified two-player, two-move model with payoffs 5/3/1/0 and no mutation."},"formula":"δ* = (T − R) / (T − P)","source":"../math/applied/prisoners-dilemma/#step3","lessons":[{"slug":"prisoners-dilemma","step":3,"category":"math","stage":"university","primary":true}],"note":"game-theory and natural-selection are page slugs; coordinator may remap to atlas node ids if they exist.","aliases":{"zh":["合作的演化","为什么要合作"],"en":["evolution of cooperation","cooperation"]}},
"recursion-divide":{"description":{"zh":"用调用栈、汉诺塔和递归树说明递归：规模怎样缩小、每层做多少事决定总代价；以归并排序展示分而治之。计数来自页面内真实执行。","en":"Explain recursion with the call stack, Towers of Hanoi and recursion trees: how the size shrinks and how much each level does set the total cost; merge sort shows divide and conquer. Counts come from code actually running on the page."},"formula":"T(n) = 2T(n−1) + 1 = 2ⁿ − 1","source":"../computing/algorithms/recursion-divide/#step2","lessons":[{"slug":"recursion-divide","step":2,"category":"computing","stage":"university","primary":true}]},
"shortest-path":{"description":{"zh":"带权图里路径代价是权重之和；迪杰斯特拉每次确认暂定距离最小的点，像洪水从起点漫开；负权会让它出错（贝尔曼–福特对照）；网格地图上泥地代价决定穿过还是绕开；A* 用启发值少确认一些格。小图与网格的教学实现，O(V²)。","en":"In a weighted graph a path’s cost is the sum of weights; Dijkstra settles the smallest tentative distance each time, like a flood from the start; negative weights make it fail (Bellman–Ford for contrast); on a grid map the mud cost decides whether to cross or go round; A* uses a heuristic to settle fewer cells. Teaching implementations on small graphs and grids, O(V²)."},"formula":"dist[v] = min(dist[u] + w(u, v))","source":"../computing/algorithms/shortest-path/#step1","lessons":[{"slug":"shortest-path","step":1,"category":"computing","stage":"university","primary":true}],"note":"graph-algorithms and pagerank are page slugs; remap if the coordinator has atlas nodes.","aliases":{"zh":["最短路径","最短路径算法","迪杰斯特拉"],"en":["shortest path","dijkstra","dijkstra's algorithm"]}},
"z-transform":{"description":{"zh":"Z 变换是采样信号的拉普拉斯变换：每隔 T 取一个样，用 z = e^{sT} 代替 s，左半平面被卷进单位圆内、虚轴卷成圆周，于是离散系统的极点在圆内稳定、在圆上持续振荡、在圆外发散。","en":"The z-transform is the Laplace transform of sampled signals: taking a sample every T and substituting z = e^{sT} rolls the left half-plane inside the unit circle and the imaginary axis onto its rim, so a discrete system’s poles are stable inside the circle, ring on it and blow up outside."},"formula":"X(z) = Σ x[n] z⁻ⁿ,  z = e^{sT}","source":"../signal/transforms/z-transform/#step0","lessons":[{"slug":"z-transform","step":0,"category":"signal","stage":"university","primary":true}],"aliases":{"zh":["Z 变换","单位圆与稳定性","离散系统的极点","收敛域","DTFT 和 Z 变换的关系","数字滤波器","z 变换"],"en":["z-transform","unit circle and stability","poles of a discrete-time system","region of convergence","DTFT vs z-transform","digital filter","z transform"]}}
}});
